insert into public.species (slug,name,latin,category_id,kind,difficulty,temperament,description,facts,keywords,is_rare,status) values
('danio-margaritatus','Galaxy Rasbora / CPD','Danio margaritatus','danio-rasboralar','fish','Orta','Barışçıl, ürkek','İnci benekli gövdesi ve kırmızı-siyah yüzgeçleriyle nano akvaryumların en tanınan sürü balıklarındandır.','[["Yetişkin boy", "2,5 cm"], ["Sıcaklık", "20–26 °C"], ["pH", "6.5–7.5"], ["Min. akvaryum", "40 L"], ["Huy", "Barışçıl, ürkek"], ["Beslenme", "Mikro omnivor"], ["Üreme", "Bitki/mop arasına yumurta saçar"], ["Köken", "Myanmar"], ["Ömür", "3–5 yıl"], ["Özellikler", "Nano, sürü, renkli"]]'::jsonb,array['galaxy rasbora / cpd','galaxy rasbora','celestial pearl danio','cpd','danio margaritatus','celestichthys margaritatus']::text[],false,'published'),
('danio-erythromicron','Emerald Dwarf Rasbora','Danio erythromicron','danio-rasboralar','fish','Orta','Barışçıl, ürkek','Dikey bantları ve küçük boyuyla bitkili nano tanklara uygun, çekingen bir daniodur.','[["Yetişkin boy", "3 cm"], ["Sıcaklık", "20–25 °C"], ["pH", "7.0–8.0"], ["Min. akvaryum", "40 L"], ["Huy", "Barışçıl, ürkek"], ["Beslenme", "Mikro omnivor"], ["Üreme", "Yumurta saçar"], ["Köken", "Myanmar, Inle Gölü havzası"], ["Ömür", "3–5 yıl"], ["Özellikler", "Nano, sürü, bantlı"]]'::jsonb,array['emerald dwarf rasbora','erythromicron','celestichthys erythromicron']::text[],true,'published'),
('danio-choprae','Glowlight Danio','Danio choprae','danio-rasboralar','fish','Kolay','Barışçıl, aktif','Turuncu çizgileri ve hareketli yapısıyla küçük-orta boy sürü akvaryumları için canlı bir türdür.','[["Yetişkin boy", "4 cm"], ["Sıcaklık", "20–26 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl, aktif"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçar"], ["Köken", "Myanmar"], ["Ömür", "3–5 yıl"], ["Özellikler", "Sürü, aktif, turuncu"]]'::jsonb,array['glowlight danio','choprae','choprai']::text[],false,'published'),
('danio-rerio-var-frankei','Leopar Danio','Danio rerio var. frankei','danio-rasboralar','fish','Kolay','Barışçıl, çok aktif','Zebra danionun benekli akvaryum varyetesidir; dayanıklı ve çok hareketlidir.','[["Yetişkin boy", "5 cm"], ["Sıcaklık", "18–26 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl, çok aktif"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçar"], ["Köken", "Akvaryum varyetesi"], ["Ömür", "3–5 yıl"], ["Özellikler", "Sürü, dayanıklı, benekli"]]'::jsonb,array['leopard danio','frankei','leopar danio']::text[],false,'published'),
('devario-aequipinnatus','Dev Danio','Devario aequipinnatus','danio-rasboralar','fish','Kolay','Barışçıl, çok aktif','Hızlı yüzen, iri danio formunda ve geniş yüzme alanı isteyen dayanıklı bir sürü balığıdır.','[["Yetişkin boy", "10 cm"], ["Sıcaklık", "20–27 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "150 L"], ["Huy", "Barışçıl, çok aktif"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçar"], ["Köken", "Güney Asya"], ["Ömür", "4–6 yıl"], ["Özellikler", "Sürü, hızlı, iri"]]'::jsonb,array['giant danio','devario aequipinnatus','dev danio']::text[],false,'published'),
('devario-malabaricus','Malabar Danio','Devario malabaricus','danio-rasboralar','fish','Kolay','Barışçıl, aktif','Uzun gövdesi ve mavi-sarı çizgileriyle güçlü akıntıya uyumlu aktif bir sürü balığıdır.','[["Yetişkin boy", "12 cm"], ["Sıcaklık", "20–27 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "180 L"], ["Huy", "Barışçıl, aktif"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçar"], ["Köken", "Hindistan"], ["Ömür", "4–6 yıl"], ["Özellikler", "Sürü, akıntı, aktif"]]'::jsonb,array['malabar danio','devario malabaricus']::text[],true,'published'),
('boraras-brigittae','Sivrisinek Rasbora','Boraras brigittae','danio-rasboralar','fish','Orta','Barışçıl, ürkek','Yoğun kırmızı rengiyle çok küçük, sakin ve yumuşak su nano akvaryumlarının gözde türüdür.','[["Yetişkin boy", "2 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "4.0–7.0"], ["Min. akvaryum", "30 L"], ["Huy", "Barışçıl, ürkek"], ["Beslenme", "Mikro omnivor"], ["Üreme", "Bitkiler arasına yumurta saçar"], ["Köken", "Borneo"], ["Ömür", "3–5 yıl"], ["Özellikler", "Nano, kırmızı, siyah su"]]'::jsonb,array['sivrisinek rasbora','chili rasbora','mosquito rasbora','boraras brigittae']::text[],false,'published'),
('boraras-merah','Phoenix Rasbora','Boraras merah','danio-rasboralar','fish','Orta','Barışçıl, ürkek','Kırmızı gövdesindeki koyu yan lekesiyle çok küçük ve narin bir Borneo türüdür.','[["Yetişkin boy", "2 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "4.0–7.0"], ["Min. akvaryum", "30 L"], ["Huy", "Barışçıl, ürkek"], ["Beslenme", "Mikro omnivor"], ["Üreme", "Yumurta saçar"], ["Köken", "Borneo"], ["Ömür", "3–5 yıl"], ["Özellikler", "Nano, kırmızı, siyah su"]]'::jsonb,array['phoenix rasbora','boraras merah']::text[],true,'published'),
('boraras-maculatus','Cüce Rasbora','Boraras maculatus','danio-rasboralar','fish','Orta','Barışçıl','Kırmızımsı gövde üzerindeki siyah lekeleriyle klasik nano sürü balıklarındandır.','[["Yetişkin boy", "2,5 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "4.0–7.0"], ["Min. akvaryum", "30 L"], ["Huy", "Barışçıl"], ["Beslenme", "Mikro omnivor"], ["Üreme", "Yumurta saçar"], ["Köken", "Güneydoğu Asya"], ["Ömür", "3–5 yıl"], ["Özellikler", "Nano, sürü, siyah su"]]'::jsonb,array['cüce rasbora','dwarf rasbora','boraras maculatus']::text[],false,'published'),
('boraras-urophthalmoides','Exclamation Point Rasbora','Boraras urophthalmoides','danio-rasboralar','fish','Orta','Barışçıl','Yan çizgisindeki ünlem işaretini andıran desenle tanınan çok küçük bir sürü balığıdır.','[["Yetişkin boy", "2 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "5.0–7.0"], ["Min. akvaryum", "30 L"], ["Huy", "Barışçıl"], ["Beslenme", "Mikro omnivor"], ["Üreme", "Yumurta saçar"], ["Köken", "Güneydoğu Asya"], ["Ömür", "3–5 yıl"], ["Özellikler", "Nano, sürü, minik"]]'::jsonb,array['exclamation point rasbora','urophthalmoides']::text[],true,'published'),
('trigonostigma-espei','Espei Rasbora','Trigonostigma espei','danio-rasboralar','fish','Kolay','Barışçıl','Bakır-turuncu gövdesi ve siyah kama deseniyle bitkili akvaryumlara çok yakışan sürü balığıdır.','[["Yetişkin boy", "4 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl"], ["Beslenme", "Omnivor"], ["Üreme", "Yaprak altına yumurta bırakır"], ["Köken", "Güneydoğu Asya"], ["Ömür", "4–6 yıl"], ["Özellikler", "Sürü, turuncu, bitkili"]]'::jsonb,array['lambchop rasbora','espei rasbora','trigonostigma espei']::text[],false,'published'),
('trigonostigma-hengeli','Hengeli Rasbora','Trigonostigma hengeli','danio-rasboralar','fish','Kolay','Barışçıl','İnce turuncu parıltısı ve siyah kama deseniyle zarif, barışçıl bir sürü balığıdır.','[["Yetişkin boy", "3,5 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "5.0–7.5"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl"], ["Beslenme", "Omnivor"], ["Üreme", "Yaprak altına yumurta bırakır"], ["Köken", "Sumatra ve Borneo"], ["Ömür", "4–6 yıl"], ["Özellikler", "Sürü, zarif, turuncu"]]'::jsonb,array['hengeli rasbora','hengel''s rasbora','glowlight rasbora','trigonostigma hengeli']::text[],false,'published'),
('microdevario-kubotai','Kubotai Rasbora','Microdevario kubotai','danio-rasboralar','fish','Orta','Barışçıl, aktif','Floresan yeşil rengi ve sürekli hareketiyle küçük bitkili tanklarda çok dikkat çeken sürü balığıdır.','[["Yetişkin boy", "3 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "50 L"], ["Huy", "Barışçıl, aktif"], ["Beslenme", "Mikro omnivor"], ["Üreme", "Yumurta saçar"], ["Köken", "Myanmar ve Tayland"], ["Ömür", "3–5 yıl"], ["Özellikler", "Nano, yeşil, sürü"]]'::jsonb,array['kubotai rasbora','microdevario kubotai','neon green rasbora','kubotai']::text[],false,'published'),
('rasbora-trilineata','Scissortail Rasbora','Rasbora trilineata','danio-rasboralar','fish','Kolay','Barışçıl, aktif','Makas desenli kuyruğu ve hızlı yüzüşüyle geniş tank isteyen orta boy bir sürü balığıdır.','[["Yetişkin boy", "13 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "5.0–8.0"], ["Min. akvaryum", "180 L"], ["Huy", "Barışçıl, aktif"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçar"], ["Köken", "Güneydoğu Asya"], ["Ömür", "5–7 yıl"], ["Özellikler", "Sürü, hızlı, iri"]]'::jsonb,array['scissortail rasbora','rasbora trilineata']::text[],false,'published'),
('rasbora-einthovenii','Brilliant Rasbora','Rasbora einthovenii','danio-rasboralar','fish','Kolay','Barışçıl','Koyu yan çizgisi ve gümüş gövdesiyle doğal görünümlü, aktif bir Güneydoğu Asya türüdür.','[["Yetişkin boy", "9 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "5.0–7.5"], ["Min. akvaryum", "120 L"], ["Huy", "Barışçıl"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçar"], ["Köken", "Güneydoğu Asya"], ["Ömür", "4–6 yıl"], ["Özellikler", "Sürü, doğal, aktif"]]'::jsonb,array['brilliant rasbora','einthovenii']::text[],true,'published'),
('rasbora-borapetensis','Kırmızı Kuyruk Rasbora','Rasbora borapetensis','danio-rasboralar','fish','Kolay','Barışçıl','Belirgin koyu yan çizgisi ve kırmızı kuyruk bölgesiyle dayanıklı bir sürü balığıdır.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "80 L"], ["Huy", "Barışçıl"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçar"], ["Köken", "Güneydoğu Asya"], ["Ömür", "4–6 yıl"], ["Özellikler", "Sürü, kırmızı kuyruk"]]'::jsonb,array['kırmızı kuyruk rasbora','blackline rasbora','red tail rasbora','borapetensis']::text[],false,'published'),
('laubuka-dadiburjori','Dadio','Laubuka dadiburjori','danio-rasboralar','fish','Orta','Barışçıl, aktif','Küçük, yüzeye yakın gezen ve ince desenli yapısıyla özel sürü akvaryumlarına uygun bir türdür.','[["Yetişkin boy", "4 cm"], ["Sıcaklık", "22–27 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl, aktif"], ["Beslenme", "Mikro omnivor"], ["Üreme", "Yumurta saçar"], ["Köken", "Hindistan"], ["Ömür", "3–5 yıl"], ["Özellikler", "Sürü, yüzey, nadir"]]'::jsonb,array['dadıburjor rasbora','laubuka dadiburjori','dadio']::text[],true,'published'),
('danio-tinwini','Gold Ring Danio','Danio tinwini','danio-rasboralar','fish','Orta','Barışçıl, aktif','Altın zemin üzerindeki koyu benekleriyle küçük ve aktif bir Myanmar daniosudur.','[["Yetişkin boy", "3 cm"], ["Sıcaklık", "20–26 °C"], ["pH", "6.5–7.5"], ["Min. akvaryum", "50 L"], ["Huy", "Barışçıl, aktif"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçar"], ["Köken", "Myanmar"], ["Ömür", "3–5 yıl"], ["Özellikler", "Nano, benekli, aktif"]]'::jsonb,array['altın cüce barb / gold ring danio','danio tinwini','gold ring danio']::text[],true,'published'),
('danio-aesculapii','Panther Danio','Danio aesculapii','danio-rasboralar','fish','Orta','Barışçıl','Leopar benzeri deseni ve küçük boyuyla nadir bulunan zarif bir daniodur.','[["Yetişkin boy", "4 cm"], ["Sıcaklık", "20–26 °C"], ["pH", "6.5–7.5"], ["Min. akvaryum", "50 L"], ["Huy", "Barışçıl"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçar"], ["Köken", "Myanmar"], ["Ömür", "3–5 yıl"], ["Özellikler", "Sürü, benekli, nadir"]]'::jsonb,array['danio aesculapii','panther danio']::text[],true,'published'),
('rasbora-daniconius','Blackline Rasbora','Rasbora daniconius','danio-rasboralar','fish','Kolay','Barışçıl, aktif','Belirgin siyah yan çizgisi bulunan, dayanıklı ve orta boy bir Güney Asya sürü balığıdır.','[["Yetişkin boy", "10 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "140 L"], ["Huy", "Barışçıl, aktif"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçar"], ["Köken", "Güney Asya"], ["Ömür", "4–6 yıl"], ["Özellikler", "Sürü, aktif, dayanıklı"]]'::jsonb,array['rasbora daniconius','blackline rasbora']::text[],true,'published')
insert into public.species (slug,name,latin,category_id,kind,difficulty,temperament,description,facts,keywords,is_rare,status) values
('chromobotia-macracanthus','Palyaço Loach','Chromobotia macracanthus','loachlar','fish','Orta','Sosyal, hareketli','Turuncu gövdesindeki üç siyah bantla tanınan, sosyal ve uzun ömürlü; erişkinde oldukça irileşen loachtur.','[["Yetişkin boy", "30 cm"], ["Sıcaklık", "25–30 °C"], ["pH", "5.0–8.0"], ["Min. akvaryum", "450 L"], ["Huy", "Sosyal, hareketli"], ["Beslenme", "Omnivor"], ["Üreme", "Doğada yağış dönemiyle ilişkili; ev akvaryumunda zor"], ["Köken", "Sumatra ve Borneo"], ["Ömür", "15–25+ yıl"], ["Özellikler", "Loach, sürü, iri"]]'::jsonb,array['palyaço loach','clown loach','botia macracanthus','chromobotia macracanthus']::text[],false,'published'),
('ambastaia-sidthimunki','Cüce Zincir Loach','Ambastaia sidthimunki','loachlar','fish','Orta','Sosyal, hareketli','Zincir benzeri deseni ve gündüz aktif davranışıyla küçük loachlar arasında en sevilen türlerdendir.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "90 L"], ["Huy", "Sosyal, hareketli"], ["Beslenme", "Omnivor"], ["Üreme", "Akvaryumda üretimi zordur"], ["Köken", "Tayland"], ["Ömür", "8–12 yıl"], ["Özellikler", "Loach, küçük, sosyal"]]'::jsonb,array['cüce zincir loach','dwarf chain loach','sidthimunki','yasuhikotakia sidthimunki']::text[],false,'published'),
('botia-striata','Zebra Loach','Botia striata','loachlar','fish','Orta','Sosyal','İnce zebra çizgileriyle tanınan, grup halinde bakılması gereken orta boy bir loachtur.','[["Yetişkin boy", "9 cm"], ["Sıcaklık", "23–27 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "120 L"], ["Huy", "Sosyal"], ["Beslenme", "Omnivor"], ["Üreme", "Akvaryumda zor"], ["Köken", "Hindistan"], ["Ömür", "8–12 yıl"], ["Özellikler", "Loach, zebra, sosyal"]]'::jsonb,array['zebra loach','botia striata']::text[],false,'published'),
('botia-almorhae','Yoyo Loach','Botia almorhae','loachlar','fish','Orta','Sosyal, hareketli','Genç bireylerde Y-O-Y-O harflerini andıran deseniyle bilinen hareketli ve meraklı bir türdür.','[["Yetişkin boy", "15 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "180 L"], ["Huy", "Sosyal, hareketli"], ["Beslenme", "Omnivor"], ["Üreme", "Akvaryumda zor"], ["Köken", "Güney Asya"], ["Ömür", "10–15 yıl"], ["Özellikler", "Loach, aktif, salyangoz"]]'::jsonb,array['yoyo loach','pakistani loach','botia almorhae']::text[],false,'published'),
('botia-kubotai','Myanmar Border Loach','Botia kubotai','loachlar','fish','Orta','Sosyal','Ağsı siyah-beyaz deseni erişkinlikle değişen, sosyal ve aktif bir loachtur.','[["Yetişkin boy", "12 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "150 L"], ["Huy", "Sosyal"], ["Beslenme", "Omnivor"], ["Üreme", "Akvaryumda zor"], ["Köken", "Myanmar-Tayland sınırı"], ["Ömür", "10–15 yıl"], ["Özellikler", "Loach, desenli, sosyal"]]'::jsonb,array['myanmar border loach','botia kubotai','polka dot loach']::text[],false,'published'),
('yasuhikotakia-modesta','Mavi Botia','Yasuhikotakia modesta','loachlar','fish','Zor','Yarı agresif, sosyal','Mavi-gri gövde ve kırmızı yüzgeçleriyle iri, güçlü ve hiyerarşik bir loachtur.','[["Yetişkin boy", "25 cm"], ["Sıcaklık", "24–30 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "350 L"], ["Huy", "Yarı agresif, sosyal"], ["Beslenme", "Omnivor"], ["Üreme", "Akvaryumda zor"], ["Köken", "Mekong havzası"], ["Ömür", "12–20 yıl"], ["Özellikler", "Loach, iri, mavi"]]'::jsonb,array['mavi botia','blue botia','redtail botia','yasuhikotakia modesta']::text[],true,'published'),
('pangio-kuhlii','Kuhli Loach','Pangio kuhlii','loachlar','fish','Kolay','Barışçıl, gececi','Yılanımsı gövdesi ve gececi davranışıyla sakin dip akvaryumlarının klasik türlerinden biridir.','[["Yetişkin boy", "10 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "70 L"], ["Huy", "Barışçıl, gececi"], ["Beslenme", "Omnivor/detritivor"], ["Üreme", "Akvaryumda nadir ürer"], ["Köken", "Güneydoğu Asya"], ["Ömür", "8–12 yıl"], ["Özellikler", "Dip, gececi, yılanımsı"]]'::jsonb,array['kuhli loach','pangio kuhlii']::text[],false,'published'),
('pangio-semicincta','Bantlı Kuhli','Pangio semicincta','loachlar','fish','Kolay','Barışçıl, gececi','Ticarette sıkça kuhli adıyla satılan, bantlı ve gece aktif küçük bir dip balığıdır.','[["Yetişkin boy", "9 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "70 L"], ["Huy", "Barışçıl, gececi"], ["Beslenme", "Omnivor/detritivor"], ["Üreme", "Akvaryumda nadir"], ["Köken", "Malay Yarımadası ve Sunda bölgesi"], ["Ömür", "8–12 yıl"], ["Özellikler", "Dip, bantlı, gececi"]]'::jsonb,array['bantlı kuhli','pangio semicincta','banded kuhli loach']::text[],false,'published'),
('pangio-oblonga','Java Loach','Pangio oblonga','loachlar','fish','Kolay','Barışçıl','Tek renk koyu kahverengi gövdesiyle diğer kuhli türlerinden ayrılan sakin, gececi bir loachtur.','[["Yetişkin boy", "10 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "5.0–7.5"], ["Min. akvaryum", "70 L"], ["Huy", "Barışçıl"], ["Beslenme", "Omnivor/detritivor"], ["Üreme", "Akvaryumda nadir"], ["Köken", "Güneydoğu Asya"], ["Ömür", "8–12 yıl"], ["Özellikler", "Dip, gececi, kahverengi"]]'::jsonb,array['java loach','black kuhli','pangio oblonga']::text[],false,'published'),
('sewellia-lineolata','Hillstream Loach','Sewellia lineolata','loachlar','fish','Orta','Barışçıl, bölgeci','Vantuz benzeri gövde yapısıyla hızlı, oksijence zengin akarsulara uyum sağlamış özel bir loachtur.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "20–25 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "80 L"], ["Huy", "Barışçıl, bölgeci"], ["Beslenme", "Alg-biofilm ve küçük omurgasız"], ["Üreme", "Taş yüzeylere yumurta; akvaryumda mümkün"], ["Köken", "Vietnam ve Laos"], ["Ömür", "5–8 yıl"], ["Özellikler", "Akıntı, biofilm, hillstream"]]'::jsonb,array['hillstream loach','sewellia lineolata','reticulated hillstream loach']::text[],false,'published'),
